CREATE TABLE institutional_flows(provider text NOT NULL,fund text NOT NULL,asset text NOT NULL,report_date date NOT NULL,published_at timestamptz NOT NULL,net_flow_usd numeric,source_url text NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(provider,fund,report_date));
CREATE TABLE macro_events(id text PRIMARY KEY,event text NOT NULL,event_at timestamptz NOT NULL,country text NOT NULL,impact text NOT NULL,actual numeric,estimate numeric,previous numeric,source_url text NOT NULL,received_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE signal_evaluations(alert_id uuid PRIMARY KEY REFERENCES alerts(id) ON DELETE CASCADE,horizon_hours integer NOT NULL,entry_price numeric NOT NULL,exit_price numeric NOT NULL,return_percent numeric NOT NULL,observed_at timestamptz NOT NULL,description text NOT NULL);
